// Package testkit holds helpers for tests only: the goldens and the log corpus under
// collector/testdata (plan Task 1). The goldens were generated by collector/testdata/gen_golden.py
// running the former Python collector; both were removed on 2026-10-22 (see git history). Test
// comments that name gen_golden or .venv Python cite that generator and that interpreter. No
// production package imports it.
package testkit

import (
	"bytes"
	"encoding/json"
	"io"
	"os"
	"path"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
	"time"
)

// TestdataDir is the absolute path of collector/testdata, found from this source file so tests in
// any package can reach it.
func TestdataDir(t testing.TB) string {
	t.Helper()
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("testkit: cannot locate its own source file")
	}
	return filepath.Join(filepath.Dir(file), "..", "..", "testdata")
}

// Golden loads collector/testdata/golden/<name> (".json" is appended when name has no extension)
// into v. A *[]byte receives the raw bytes, so a caller can decode with pyjson to keep key order and
// the int/float distinction; anything else goes through encoding/json.
func Golden(t testing.TB, name string, v any) {
	t.Helper()
	if filepath.Ext(name) == "" {
		name += ".json"
	}
	data, err := os.ReadFile(filepath.Join(TestdataDir(t), "golden", name))
	if err != nil {
		t.Fatalf("testkit: golden %s: %v", name, err)
	}
	if raw, ok := v.(*[]byte); ok {
		*raw = data
		return
	}
	dec := json.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(v); err != nil {
		t.Fatalf("testkit: golden %s: %v", name, err)
	}
}

// Mtimes returns collector/testdata/mtimes.json: corpus path (relative to collector/testdata, slash
// separated: "logs/...", "fixtures/...") → [sec, nsec].
func Mtimes(t testing.TB) map[string][2]int64 {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(TestdataDir(t), "mtimes.json"))
	if err != nil {
		t.Fatalf("testkit: mtimes.json: %v", err)
	}
	var m map[string][2]int64
	if err := json.Unmarshal(data, &m); err != nil {
		t.Fatalf("testkit: mtimes.json: %v", err)
	}
	return m
}

// CopyCorpus copies collector/testdata/logs/<rel> (a directory or one file) into t.TempDir() and
// gives every copied file the mtime mtimes.json records for it, as the former golden generator
// (gen_golden.py, removed with the Python collector) did with os.utime(ns=…). It returns the
// copy's path: the copied directory itself, or the copied file.
//
// rel is slash-separated and relative to testdata/logs; "../fixtures/..." reaches the fixtures.
// The mtimes.json key of a file is path.Clean("logs/" + rel + "/" + its path inside rel). A *.jsonl
// file without an entry fails the test, as gen_golden.py failed on one.
func CopyCorpus(t testing.TB, rel string) string {
	t.Helper()
	td := TestdataDir(t)
	key := path.Clean("logs/" + rel)
	if key == ".." || strings.HasPrefix(key, "../") {
		t.Fatalf("testkit: CopyCorpus(%q) leaves collector/testdata", rel)
	}
	src := filepath.Join(td, filepath.FromSlash(key))
	info, err := os.Stat(src)
	if err != nil {
		t.Fatalf("testkit: CopyCorpus: %v", err)
	}
	mtimes := Mtimes(t)
	dst := filepath.Join(t.TempDir(), filepath.Base(src))

	copyOne := func(from, to, k string) {
		if err := os.MkdirAll(filepath.Dir(to), 0o755); err != nil {
			t.Fatalf("testkit: CopyCorpus: %v", err)
		}
		if err := copyFile(from, to); err != nil {
			t.Fatalf("testkit: CopyCorpus: %v", err)
		}
		mt, ok := mtimes[k]
		if !ok {
			if strings.HasSuffix(k, ".jsonl") {
				t.Fatalf("testkit: CopyCorpus: %s has no mtimes.json entry", k)
			}
			return
		}
		ts := time.Unix(mt[0], mt[1])
		if err := os.Chtimes(to, ts, ts); err != nil {
			t.Fatalf("testkit: CopyCorpus: %v", err)
		}
	}

	if !info.IsDir() {
		copyOne(src, dst, key)
		return dst
	}
	err = filepath.WalkDir(src, func(p string, d os.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return err
		}
		r, err := filepath.Rel(src, p)
		if err != nil {
			return err
		}
		copyOne(p, filepath.Join(dst, r), path.Join(key, filepath.ToSlash(r)))
		return nil
	})
	if err != nil {
		t.Fatalf("testkit: CopyCorpus: %v", err)
	}
	return dst
}

func copyFile(from, to string) error {
	in, err := os.Open(from)
	if err != nil {
		return err
	}
	defer in.Close()
	out, err := os.Create(to)
	if err != nil {
		return err
	}
	if _, err := io.Copy(out, in); err != nil {
		out.Close()
		return err
	}
	return out.Close()
}
